<script setup>
import { computed } from 'vue';
import { ACTIVITIES } from '../lib/nutrition.js';
import AppIcon from '../components/AppIcon.vue';
const props=defineProps({ profile:Object,nutrition:Object,flags:Array,preferences:String });
const activity=computed(()=>ACTIVITIES.find(item=>item.key===props.profile.activity));
const emit=defineEmits(['edit','update:flags','update:preferences']);
const choices=['正在使用药物','孕期或哺乳期','有需要管理的健康状况','正在使用营养补充剂'];
function toggle(value,checked,flags){emit('update:flags',checked ? [...flags,value] : flags.filter(item=>item!==value));}
</script>
<template><div class="vb-page-title"><div><p class="vb-eyebrow">随身体与生活变化，随时更新</p><h1>个人档案</h1><p>身体档案支持整体跳过。主页支持0—120岁年龄段参考卡片；婴幼儿、青少年和高龄采用对应分组并注明范围，资料缺失时保持未知。</p></div><button class="vb-button vb-button-primary" @click="$emit('edit')"><AppIcon name="edit" :size="17" />修改基础档案</button></div><section class="vb-glass vb-profile-details"><div class="vb-section-heading"><h2>基础信息</h2><span class="vb-pill">本地保存</span></div><dl><div><dt>生理性别</dt><dd>{{ profile.sex==='male'?'男性':profile.sex==='female'?'女性':'未填写' }}</dd></div><div><dt>年龄</dt><dd>{{ profile.age == null || profile.age === '' ? '未填写' : `${profile.age} 岁` }}</dd></div><div><dt>身高</dt><dd>{{ profile.height == null || profile.height === '' ? '未填写' : `${profile.height} cm` }}</dd></div><div><dt>体重</dt><dd>{{ profile.weight == null || profile.weight === '' ? '未填写' : `${profile.weight} kg` }}</dd></div><div><dt>每日活动</dt><dd>{{ activity?.label || '未填写' }}</dd></div><div><dt>活动系数</dt><dd>{{ activity ? '× ' + activity.factor : '未填写' }}</dd></div></dl></section><div class="vb-profile-settings"><section class="vb-glass"><div class="vb-section-heading"><div><h2>饮食偏好</h2><p>记下喜欢、回避或需要核对的食物</p></div><AppIcon name="bowl" /></div><label class="vb-field"><span class="vb-sr-only">饮食偏好备注</span><textarea :value="preferences" rows="5" maxlength="200" placeholder="如：偏爱家常菜，不喜欢香菜…" @input="$emit('update:preferences',$event.target.value)" /></label><p class="vb-section-note">用于饮食备忘和下一餐默认偏好；显式忌口请在规划中单独填写，不能自动验证过敏原。</p></section><section class="vb-glass"><div class="vb-section-heading"><div><h2>需要谨慎核对的情况</h2><p>可选，用于显示相应安全提醒</p></div><AppIcon name="shield" /></div><label v-for="choice in choices" :key="choice" class="vb-check-row"><input type="checkbox" :checked="flags.includes(choice)" @change="toggle(choice,$event.target.checked,flags)" /><span>{{ choice }}</span></label><p class="vb-section-note">此处标记不会改变通用 DRIs 表。特殊生理或健康需求应由专业人员评估。</p></section></div></template>
